def comprehensive_protein_analysis(file_object):
    """Parses FASTA data and performs both basic and advanced sequence analyses."""
    # Parse records using Bio.SeqIO
    records = list(SeqIO.parse(file_object, "fasta"))

    if not records:
        print("No protein records found.")
        return

    print(f"Total Proteins Loaded: {len(records)}\n")

    # 1. Length Statistics & Advanced Biochemical Properties Table
    print("=" * 80)
    print(f"{'Header':<15} | {'Length':<6} | {'Mol. Weight':<12} | {'Isoelectric Pt':<15} | {'GRAVY'}")
    print("=" * 80)

    all_sequences = ""
    lengths = []

    for record in records:
        seq_str = str(record.seq).replace("*", "")  # Clean sequence of stop codons
        all_sequences += seq_str
        seq_len = len(seq_str)
        lengths.append((record.id, seq_len))

        if seq_len > 0:
            analysed = ProteinAnalysis(seq_str)
            mol_weight = analysed.molecular_weight()
            pi_val = analysed.isoelectric_point()
            gravy_val = analysed.gravy()

            print(f"{record.id:<15} | {seq_len:<6} | {mol_weight:<12.2f} | {pi_val:<15.2f} | {gravy_val:.2f}")

    print("=" * 80)

    # Sort lengths to find shortest/longest
    lengths.sort(key=lambda x: x[1], reverse=True)
    print(f"\nLongest Protein:  {lengths[0][0]} ({lengths[0][1]} aa)")
    print(f"Shortest Protein: {lengths[-1][0]} ({lengths[-1][1]} aa)")

    # 2. Global Amino Acid Composition & Frequencies
    aa_counts = Counter(all_sequences)
    total_aas = len(all_sequences)

    print("\nGlobal Amino Acid Frequencies:")
    for aa, count in aa_counts.most_common():
        percentage = (count / total_aas) * 100 if total_aas > 0 else 0
        print(f"  {aa}: {count} ({percentage:.2f}%)")

if __name__ == "__main__":
    # To run using a local FASTA file instead, uncomment the lines below:
    # with open("proteins.fasta", "r") as file_handle:
    #     comprehensive_protein_analysis(file_handle)

    # Running analysis on the sample data string
    file_like_obj = StringIO(fasta_data.strip())
    comprehensive_protein_analysis(file_like_obj)